import java.util.*;

public class Main {
    ListNode middleNode(ListNode head) {
        int length = 0;
        for (ListNode node = head; node != null; node = node.next) length++;       // first pass: count the total number of nodes
        ListNode node = head;
        for (int i = 0; i < length / 2; i++) node = node.next;                      // second pass: walk exactly halfway to reach the middle
        return node;
    }

    public static void main(String[] args) {
        Main solution = new Main();
        ListNode head = new ListNode(1, new ListNode(2, new ListNode(3, new ListNode(4, new ListNode(5)))));
        ListNode result = solution.middleNode(head);
        StringBuilder sb = new StringBuilder();
        while (result != null) { sb.append(result.val).append(" "); result = result.next; }
        System.out.println(sb.toString().trim());
    }
}

