#include <bits/stdc++.h>
using namespace std;

ListNode* middleNode(ListNode* head) {
    int length = 0;
    for (ListNode* node = head; node; node = node->next) length++;               // first pass: count the total number of nodes
    ListNode* node = head;
    for (int i = 0; i < length / 2; i++) node = node->next;                        // second pass: walk exactly halfway to reach the middle
    return node;
}

int main() {
    ListNode* head = new ListNode(1, new ListNode(2, new ListNode(3, new ListNode(4, new ListNode(5)))));
    ListNode* result = middleNode(head);
    while (result) { cout << result->val << " "; result = result->next; }
    cout << endl;
    return 0;
}

